import{_ as a,c as t,o as r,ah as o}from"./chunks/framework.BaqsfJuc.js";const p=JSON.parse('{"title":"ADR 007: Immutable Decoded Frame Types","description":"","frontmatter":{},"headers":[],"relativePath":"adr/007-immutable-frame-types.md","filePath":"adr/007-immutable-frame-types.md","lastUpdated":1763898043000}'),s={name:"adr/007-immutable-frame-types.md"};function n(i,e,d,l,c,m){return r(),t("div",null,[...e[0]||(e[0]=[o('<h1 id="adr-007-immutable-decoded-frame-types" tabindex="-1">ADR 007: Immutable Decoded Frame Types <a class="header-anchor" href="#adr-007-immutable-decoded-frame-types" aria-label="Permalink to “ADR 007: Immutable Decoded Frame Types”">​</a></h1><ul><li><strong>Date</strong>: 2025-11-23</li><li><strong>Status</strong>: Accepted</li><li><strong>Tags</strong>: protocol, frames, type-safety</li><li><strong>Relates to</strong>: ADR 002, ADR 003</li></ul><h2 id="context" tabindex="-1">Context <a class="header-anchor" href="#context" aria-label="Permalink to “Context”">​</a></h2><p>Decoded <code>Frame</code> types are currently mutable, allowing downstream code to reassign <code>kind</code>, <code>subject</code>, <code>data</code> after <code>decodeFrame()</code>. This violates &quot;predictable, hard-to-misuse APIs&quot; and &quot;correctness first&quot; principles—frame mutation can corrupt RPC correlation, routing, and middleware state.</p><p>The protocol library is the single source of truth for wire values; decoded frames must be immutable facts.</p><h2 id="decision" tabindex="-1">Decision <a class="header-anchor" href="#decision" aria-label="Permalink to “Decision”">​</a></h2><p>All public frame types and their decoded instances are deeply readonly via TypeScript&#39;s <code>readonly</code> keyword on all properties and <code>Readonly&lt;Uint8Array&gt;</code> for binary data. Factory functions and <code>decodeFrame()</code> return immutable variants. Internal codec may use mutable temporaries during construction.</p><h2 id="consequences" tabindex="-1">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to “Consequences”">​</a></h2><ul><li><strong>Eliminates mutation bugs</strong>: TypeScript prevents reassignment of any frame property or binary data at compile time.</li><li><strong>Guarantees referential stability</strong>: Middleware, RPC handlers, and routing logic can safely pass frames without fear of corruption.</li><li><strong>Zero runtime cost</strong>: <code>readonly</code> is TS-only; no performance overhead.</li><li><strong>Breaking change for mutating code</strong>: Code that reassigns frame properties will fail type check. This is intentional—correct usage never mutates decoded frames.</li></ul><h2 id="rationale" tabindex="-1">Rationale <a class="header-anchor" href="#rationale" aria-label="Permalink to “Rationale”">​</a></h2><p>Immutability is the standard for protocol message structures across Protocol Buffers, WebRTC, and similar systems. Decoded frames represent facts from the wire and should not be reassigned downstream. This change prevents subtle bugs while maintaining full expressivity: callers that need mutable state can explicitly copy via <code>new Uint8Array(frame.data)</code>.</p>',11)])])}const f=a(s,[["render",n]]);export{p as __pageData,f as default};
